rt/strict`\n2. Import the target implementation as a namespace (not named imports)\n3. Use `mkdtempSync` and test cleanup\n4. Do not use network, child processes, environment variables, dynamic imports, clocks, randomness, timers, or sleeps\n5. Write tests, not implementation\n6. Every test vector id must be the exact test name so host TAP output witnesses execution\n7. The artifact must fail against the supplied incumbent because of behavioral assertions, not syntax errors\n8. Use one static namespace import of the target implementation\n\nTest vectors:\n1. `exact-loopback-tcp-territory` - tests that capacity and occupancy sets are derived from a snapshot, occupied/admissible and available/admissible are reduced exact fractions, each admissible berth has exact share 1/N\n2. `typed-observation-refusal` - tests that a typed refusal identifies missing observation, no zero measurement is fabricated\n\nThe implementation path should be relative to the declared artifactPath. Since the artifact is at `union-acceptance/linux-socket-territory-observation-capcell-fabrication.test.mjs`, the implementation would likely be at a sibling path.\n\nLooking at the forbidden items:\n- floating point\n- price claim\n- socket mutation\n- fixed port denominator\n- partial mutation\n- timeout-as-capacity\n- unknown-as-zero\n\nLet me construct the test file that:\n1. Imports the implementation as a namespace\n2. Tests the two scenarios\n3. Uses proper assertions\n4. Follows all the constraints\n\nThe implementation path would typically be something like `../linux-socket-territory-observation-capcell.mjs` or similar, but since I need to write tests that import it as a namespace, I'll use a relative path.\n\nLet me write the test file:\nI'll construct the acceptance test artifact based on the requirements. This test file must validate a Linux socket territory observation capability cell.\n\n```javascript\nimport { describe, it } from 'node:test'\nimport assert from 'node:assert/strict'\nimport { mkdtempSync, rmSync } from 'node:fs'\nimport { join } from 'node:path'\nimport { tmpdir } from 'node:os'\n\n// Import implementation as namespace (static import)\nimport * as impl from '../linux-socket-territory-observation-capcell.mjs'\n\ndescribe('exact-loopback-tcp-territory', () => {\n  const tempDir = mkdtempSync(join(tmpdir(), 'socket-territory-test-'))\n\n  // Cleanup after tests\n  process.on('exit', () => {\n    try {\n      rmSync(tempDir, { recursive: true, force: true })\n    } catch {}\n  })\n\n  it('derives capacity and occupancy sets from snapshot', () => {\n    // Injected Linux socket snapshot (simulated loopback TCP)\n    const snapshot = {\n      netns: 'init',\n      addressFamily: 'ipv4',\n      protocol: 'tcp',\n      listeners: [\n        {\n          localAddress: '127.0.0.1',\n          localPort: 8080,\n          state: 'LISTEN',\n          reuseAddr: true,\n          uid: 1000,\n          inode: 12345\n        },\n        {\n          localAddress: '127.0.0.1',\n          localPort: 8081,\n          state: 'LISTEN',\n          reuseAddr: false,\n          uid: 1000,\n          inode: 12346\n        }\n      ],\n      kernelEphemeralRange: '32768-60999',\n      kernelReservations: []\n    }\n\n    // Explicit admissibility policy\n    const policy = {\n      namespace: 'init',\n      addressFamily: 'ipv4',\n      protocol: 'tcp',\n      addressScope: 'loopback',\n      portPredicate: (port) => port >= 8000 && port < 9000\n    }\n\n    const result = impl.observeLinuxSocketTerritory({ snapshot, policy })\n\n    // Assert capacity and occupancy sets are derived\n    assert.ok(result)\n    assert.ok(result.capacity)\n    assert.ok(result.occupancy)\n    \n    // Must be arrays or objects with proper structure\n    assert.ok(typeof result.capacity === 'object' || Array.isArray(result.capacity))\n    assert.ok(typeof result.occupancy === 'object' || Array.isArray(result.occupancy))\n  })\n\n  it('derives occupied/admissible and available/admissible as reduced exact fractions', () => {\n    const snapshot = {\n      netns: 'init',\n      addressFamily: 'ipv4',\n      protocol: 'tcp',\n      listeners: [\n        {\n          localAddress: '127.0.0.1',\n          localPort: 8080,\n          state: 'LISTEN',\n          reuseAddr: true,\n          uid: 1000,\n          inode: 12345\n        }\n      ],\n      kernelEphemeralRange: '32768-60999',\n      kernelReservations: []\n    }\n\n    const policy = {\n      namespace: 'init',\n      addressFamily: 'ipv4',\n      protocol: 'tcp',\n      addressScope: 'loopback',\n      portPredicate: (port) => port >= 8000 && port < 9000\n    }\n\n    const result = impl.observeLinuxSocketTerritory({ snapshot, policy })\n\n    // Assert fractions exist and are properly structured\n    assert.ok(result.occupiedAdmissible)\n    assert.ok(result.availableAdmissible)\n\n    // Must have numerator and denominator as strings\n    assert.ok(typeof result.occupiedAdmissible.numerator === 'string')\n    assert.ok(typeof result.occupiedAdmissible.denominator === 'string')\n    assert.ok(typeof result.availableAdmissible.numerator === 'string')\n    assert.ok(typeof result.availableAdmissible.denominator === 'string')\n\n    // Denominator must be positive\n    const occDen = parseInt(result.occupiedAdmissible.denominator, 10)\n    const availDen = parseInt(result.availableAdmissible.denominator, 10)\n    assert.ok(occDen > 0, 'denominator must be positive')\n    assert.ok(availDen > 0, 'denominator must be positive')\n\n    // Numerators must be non-negative integers as strings\n    const occNum = parseInt(result.occupiedAdmissible.numerator, 10)\n    const availNum = parseInt(result.availableAdmissible.numerator, 10)\n    assert.ok(Number.isInteger(occNum) && occNum >= 0)\n    assert.ok(Number.isInteger(availNum) && availNum >= 0)\n  })\n\n  it('gives each admissible berth exact share 1/N with same referent', () => {\n    const snapshot = {\n      netns: 'init',\n      addressFamily: 'ipv4',\n      protocol: 'tcp',\n      listeners: [\n        {\n          localAddress: '127.0.0.1',\n          localPort: 8080,\n          state: 'LISTEN',\n          reuseAddr: true,\n          uid: 1000,\n          inode: 12345\n        }\n      ],\n      kernelEphemeralRange: '32768-60999',\n      kernelReservations: []\n    }\n\n    const policy = {\n      namespace: 'init',\n      addressFamily: 'ipv4',\n      protocol: 'tcp',\n      addressScope: 'loopback',\n      portPredicate: (port) => port >= 8000 && port < 9000\n    }\n\n    const result = impl.observeLinuxSocketTerritory({ snapshot, policy })\n\n    // Assert shares exist\n    assert.ok(result.shares)\n    \n    // Each share should be 1/N\n    for (const share of result.shares) {\n      assert.ok(share)\n      assert.ok(typeof share.numerator === 'string')\n      assert.ok(typeof share.denominator === 'string')\n      \n      const num = parseInt(share.numerator, 10)\n      const den = parseInt(share.denominator, 10)\n      \n      // Must be exactly 1/N\n      assert.strictEqual(num, 1, 'share numerator must be 1')\n      assert.strictEqual(typeof share.denominator, 'string', 'denominator must be string')\n      assert.ok(den > 0, 'denominator must be positive')\n    }\n\n    // All shares must have same referent (denominator)\n    if (result.shares.length > 1) {\n      const firstDen = result.shares[0].denominator\n      for (const share of result.shares) {\n        assert.strictEqual(share.denominator, firstDen, 'all shares must have same denominator')\n      }\n    }\n  })\n\n  it('does not use floating point\n"}],"omittedArtifacts":[],"priorVerifiedKnowledge":[],"priorResidueKnowledge":[],"constraints":["Expose exactly one operation: observe-linux-socket-territory.","The observed resource identity includes network namespace, address family, transport protocol, local address, port, bind/reuse semantics, privilege threshold, kernel ephemeral range, and kernel reservations.","Represent ever